template<class F>void rejects(F fn){bool bad=false;try{fn();}catch(const std::exception&){bad=true;}need(bad,"G2-05 invalid state accepted");}
void tick(CombatScene& s,int n){while(n--){s.update({});}}
CombatEntry fixture(const CombatContent& c,const SessionEntry& state,int map,TilePosition t,Direction d=Direction::Down){auto e=c.entries.at("post-pickup");e.map=map;e.session=state;e.session.flags[1]=e.session.flags[18]=true;e.pages.clear();e.positions.clear();e.directions.clear();e.through.clear();e.playerTile=t;e.direction=d;return e;}
void choiceReady(CombatScene& s){for(int n=0;n<2000&&!s.inputPromptView().cursor;++n){s.update(n%8==0?key():InputFrame{});}need(s.inputPromptView().cursor.has_value(),"G2-05 choice absent");}
void answer(CombatScene& s,int a){choiceReady(s);if(a){s.update(key(InputAction::Down));}s.update(key());}
void settle(CombatScene& s){for(int n=0;n<3000;++n){if(s.foreground()==ForegroundKind::None&&!s.dialogue().active()){return;}s.update(n%8==0?key():InputFrame{});}throw std::runtime_error("G2-05 flow stalled");}
int page(const CombatContent& c,const std::string& id,GameSession& s){auto p=c.activeVariant(c.objects.at(id),s);return p?p->page:0;}
