struct ServerDriver:G2NaturalDriver{
 using G2NaturalDriver::G2NaturalDriver;
 void monitor(int slot,bool cancel=false){walk({8,7});move(Direction::Up);tick(key());need(game.mode()==ApplicationMode::Saving,"G2-05 legal monitor absent");for(int n=0;n<200;++n){tick();}tick(key());if(cancel){tick(key(InputAction::Cancel));return;}for(int n=1;n<slot;++n){tick(key(InputAction::Down));}tick(key());need(game.mode()==ApplicationMode::Playing,"G2-05 monitor save failed");}
 void corridor(){actObject("m151-e8");actObject("m155-e6");}
 void server(){actObject("m157-e15");actObject("m160-e5");need(game.mapId()==161,"Server doorway not delivered");}
 void promptServer(){auto t=game.content().objects.at("m161-e3").tile;walk(adjacentTile(t,Direction::Down));move(Direction::Up);tick(key());}
 void returnCorridor(){actObject("m161-e4");actObject("m160-e7");need(game.mapId()==157,"Server return absent");}
 void back(){actObject("m157-e2");actObject("m155-e2");need(game.mapId()==151,"G2-05 return absent");}

};
